func inventoryStore(root string) (Inventory, error) {
	info, err := os.Lstat(root)
	if err != nil {
		return Inventory{}, err
	}
	if !info.IsDir() {
		return Inventory{}, errors.New("survivor store is not a directory")
	}
	inventory := Inventory{Accounts: make(map[string][]string)}
	err = filepath.WalkDir(root, func(path string, entry fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		relative, err := filepath.Rel(root, path)
		if err != nil {
			return err
		}
		parts := strings.Split(filepath.ToSlash(relative), "/")
		if entry.IsDir() {
			if len(parts) == 4 && parts[0] == "jetstream" && parts[2] == "streams" {
				inventory.Accounts[parts[1]] = append(inventory.Accounts[parts[1]], parts[3])
			}
			if entry.Name() == "_meta_" {
				inventory.MetaGroup = true
			}
			return nil
		}
		if !entry.Type().IsRegular() {
			return fmt.Errorf("survivor store contains a non-regular file %s", relative)
		}
		info, err := entry.Info()
		if err != nil {
			return err
		}
		inventory.Files++
		inventory.Bytes += info.Size()
		return nil
	})
	return inventory, err
}

func Backup(ctx context.Context, target RecoveryTarget, destination string, in io.Reader, out io.Writer) (err error) {
	if destination == "" || !filepath.IsAbs(destination) {
		return errors.New("backup destination must be an absolute path")
	}
	if _, err := os.Lstat(destination); err == nil {
		return errors.New("backup destination already exists")
	}
	// Compare physical paths: a symlinked ancestor must not place the
	// backup inside the store it copies (or the store inside the backup).
	store, err := filepath.EvalSymlinks(target.StoreDir)
	if err != nil {
		return fmt.Errorf("resolve survivor store: %w", err)
	}
	parent, err := filepath.EvalSymlinks(filepath.Dir(destination))
	if err != nil {
		return fmt.Errorf("resolve backup destination parent: %w", err)
	}
	physical := filepath.Join(parent, filepath.Base(destination))
	if within(physical, store) || within(store, physical) ||
		within(destination, target.StoreDir) || within(target.StoreDir, destination) {
		return errors.New("backup destination must be outside the survivor store")
	}
	inventory, err := Preflight(ctx, target, out)
	if err != nil {
		return err
	}
	if err := Confirm(ctx, in, out, "this copies the stopped survivor store. Keep the controller stopped until recovery ends.",
		"back up "+target.Cell+"/"+target.Slot); err != nil {
		return err
	}
	if err := os.Mkdir(physical, 0o700); err != nil {
		return err
	}
	defer func() {
		if err != nil {
			_ = os.RemoveAll(physical)
		}
	}()
	var manifest []string
	var copiedBytes int64
	err = filepath.WalkDir(target.StoreDir, func(path string, entry fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if err := ctx.Err(); err != nil {
			return err
		}
		relative, err := filepath.Rel(target.StoreDir, path)
		if err != nil || relative == "." {
			return err
		}
		copied := filepath.Join(physical, relative)
		if entry.IsDir() {
			return os.Mkdir(copied, 0o700)
		}
		if !entry.Type().IsRegular() {
			return fmt.Errorf("survivor store contains a non-regular file %s", relative)
		}
		sum, size, err := copyFile(path, copied)
		if err != nil {
			return err
		}
		copiedBytes += size
		manifest = append(manifest, sum+"  "+filepath.ToSlash(relative))
		return nil
	})
	if err != nil {
		return fmt.Errorf("back up survivor store: %w", err)
	}
	if err := BrokerStopped(ctx, target); err != nil {
		return fmt.Errorf("broker started during backup: %w", err)
	}
	if len(manifest) != inventory.Files || copiedBytes != inventory.Bytes {
		return fmt.Errorf("survivor store changed during backup: inventoried %d files (%d bytes), copied %d files (%d bytes)",
			inventory.Files, inventory.Bytes, len(manifest), copiedBytes)
	}
	slices.Sort(manifest)
	header := backupProvenance{Cell: target.Cell, Slot: target.Slot, StoreDir: target.StoreDir,
		TakenAt: time.Now().UTC().Truncate(time.Second)}.lines()
	if err := writeSynced(filepath.Join(physical, BackupManifestName),
		[]byte(strings.Join(append(header, manifest...), "\n")+"\n")); err != nil {
		return err
	}
	fmt.Fprintf(out, "backed up %d files to %s\n", len(manifest), destination)
	return nil
}

func within(path, root string) bool {
	relative, err := filepath.Rel(filepath.Clean(root), filepath.Clean(path))
	return err == nil && relative != ".." && !strings.HasPrefix(relative, "../")
}

func copyFile(source, destination string) (string, int64, error) {
	input, err := os.Open(source)
	if err != nil {
		return "", 0, err
	}
	defer input.Close()
	output, err := os.OpenFile(destination, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		return "", 0, err
	}
	hash := sha256.New()
	size, err := io.Copy(io.MultiWriter(output, hash), input)
	if err != nil {
		output.Close()
		return "", 0, err
	}
	if err := output.Sync(); err != nil {
		output.Close()
		return "", 0, err
	}
	if err := output.Close(); err != nil {
		return "", 0, err
	}
	return hex.EncodeToString(hash.Sum(nil)), size, nil
}

entityid_local.text:
var (
	entropy = ulid.Monotonic(rand.Reader, 0)
	mu      sync.Mutex
)

// New returns a cryptographically random ULID, monotonic within a millisecond.
func New() string { return NewAt(time.Now()) }

// NewAt stamps an ID with the record's time. The entropy reader is shared and
// serialized because the library's monotonic reader is not concurrency-safe.
func NewAt(at time.Time) string {
	mu.Lock()
	defer mu.Unlock()
	return ulid.MustNew(ulid.Timestamp(at), entropy).String()
}

// Parse accepts only nonzero, uppercase, 26-character Crockford ULIDs.
func Parse(value string) (ulid.ULID, error) {
	id, err := ulid.ParseStrict(value)
	if err != nil || id == (ulid.ULID{}) || id.String() != value {
		return ulid.ULID{}, errors.New("entity ID must be a canonical uppercase ULID")
	}
	return id, nil
}

func Valid(value string) bool {
	_, err := Parse(value)
	return err == nil
}

// Derive gives an idempotent operation a stable ULID. A zero timestamp marks
// derived identities as having no creation time; the 80 entropy bits bind the
// domain-separated input. New entities use New instead.
func Derive(domain string, values ...string) string {
	h := sha256.New()
	for _, value := range append([]string{domain}, values...) {
		var size [8]byte
		binary.BigEndian.PutUint64(size[:], uint64(len(value)))
		h.Write(size[:])
		h.Write([]byte(value))
	}
	return ulid.MustNew(0, bytes.NewReader(h.Sum(nil)[:10])).String()
}

secret_ref_local.text:
type SecretVersionReference struct {
	SecretOCID    string `json:"secret_ocid"`
	VersionNumber int64  `json:"version_number"`
}

func (reference SecretVersionReference) Validate() error {
	if !isOCID(reference.SecretOCID, "vaultsecret") || reference.VersionNumber <= 0 {
		return errors.New("OCI Vault secret reference requires an exact version")
	}
	return nil
}

func isOCID(value, kind string) bool {
	return strings.HasPrefix(value, "ocid1."+kind+".") && len(value) <= 255 &&
		!strings.ContainsAny(value, " \t\r\n")
}

region_catalog_local.text:
func IsOCIRegion(region string) bool {
	_, ok := CellForOCIRegion(region)
	return ok
}

// CellForOCIRegion maps an exact OCI region identifier back to its cell.
func CellForOCIRegion(region string) (Entry, bool) {
	for _, entry := range entries {
		if entry.OCIRegion == region {
			return entry, true
		}
	}
	return Entry{}, false
}
